import { useMemo, useState } from "react";
import { FieldFrame, PageHeader, Select } from "@autograph/components";
import { DataTableComposition, RecordDetailPanel } from "@autograph/compositions";

type Exception = { id:string; product:string; sku:string; location:string; severity:"Critical"|"Warning"; onHand:number; reorderPoint:number; daysCover:number; supplier:string; leadTime:string; packSize:number; suggested:number };
const exceptions: Exception[] = [
{id:"ex-101",product:"Organic Whole Milk 1L",sku:"DRY-1048",location:"Downtown",severity:"Critical",onHand:3,reorderPoint:18,daysCover:0.6,supplier:"North Valley Dairy",leadTime:"2 days",packSize:12,suggested:36},
{id:"ex-102",product:"Sparkling Water Lime 8pk",sku:"BEV-2281",location:"Downtown",severity:"Warning",onHand:9,reorderPoint:16,daysCover:2.1,supplier:"Clear Springs Co.",leadTime:"4 days",packSize:8,suggested:24},
{id:"ex-103",product:"Free-range Eggs 12ct",sku:"DRY-1312",location:"Riverside",severity:"Critical",onHand:2,reorderPoint:14,daysCover:0.4,supplier:"Meadow Farm Foods",leadTime:"1 day",packSize:10,suggested:30},
{id:"ex-104",product:"Sourdough Sandwich Loaf",sku:"BAK-0782",location:"Riverside",severity:"Warning",onHand:6,reorderPoint:12,daysCover:1.8,supplier:"City Bakehouse",leadTime:"1 day",packSize:6,suggested:18},
{id:"ex-105",product:"Avocado Hass Each",sku:"PRD-0426",location:"Northside",severity:"Critical",onHand:5,reorderPoint:24,daysCover:0.8,supplier:"Pacific Produce",leadTime:"3 days",packSize:24,suggested:48},
{id:"ex-106",product:"Greek Yogurt Plain 500g",sku:"DRY-1159",location:"Northside",severity:"Warning",onHand:7,reorderPoint:15,daysCover:2.3,supplier:"North Valley Dairy",leadTime:"2 days",packSize:6,suggested:18}];

export default function StockExceptions(){
 const [location,setLocation]=useState("all"); const [severity,setSeverity]=useState("all"); const [selectedId,setSelectedId]=useState("ex-101"); const [replenished,setReplenished]=useState<string[]>([]);
 const visible=useMemo(()=>exceptions.filter(i=>(location==="all"||i.location===location)&&(severity==="all"||i.severity===severity)),[location,severity]);
 const selected=exceptions.find(i=>i.id===selectedId);
 const rows=visible.map(i=>({id:i.id,product:i.product,location:i.location,severity:i.severity,stock:`${i.onHand} / ${i.reorderPoint}`,cover:`${i.daysCover} days`}));
 return <main className="min-h-screen bg-[var(--color-bg-page)] p-[var(--space-4)] text-[var(--color-text-primary)] sm:p-[var(--space-6)]"><div className="mx-auto grid max-w-[1440px] gap-[var(--space-5)]">
  <PageHeader title="Stock exceptions" subtitle={`${visible.length} low-stock products need review`} />
  <section aria-label="Exception filters" className="grid gap-[var(--space-3)] rounded-[var(--radius-panel)] border border-[var(--color-border-subtle)] bg-[var(--color-bg-surface)] p-[var(--space-4)] sm:grid-cols-2 lg:max-w-[680px]">
   <FieldFrame label="Location" htmlFor="location-filter"><Select id="location-filter" value={location} options={[{value:"all",label:"All locations"},{value:"Downtown",label:"Downtown"},{value:"Riverside",label:"Riverside"},{value:"Northside",label:"Northside"}]} onValueChange={v=>{setLocation(v);setSelectedId("")}} /></FieldFrame>
   <FieldFrame label="Severity" htmlFor="severity-filter"><Select id="severity-filter" value={severity} options={[{value:"all",label:"All severities"},{value:"Critical",label:"Critical"},{value:"Warning",label:"Warning"}]} onValueChange={v=>{setSeverity(v);setSelectedId("")}} /></FieldFrame>
  </section>
  <div className="grid items-start gap-[var(--space-5)] lg:grid-cols-[minmax(0,1.45fr)_minmax(360px,0.85fr)]">
   <section aria-label="Low-stock products"><DataTableComposition spec={{type:"data_table",config:{ariaLabel:"Low-stock products",columns:[{id:"product",label:"Product"},{id:"location",label:"Location"},{id:"severity",label:"Severity"},{id:"stock",label:"On hand / reorder"},{id:"cover",label:"Cover"}],rows,density:"compact",narrowLayout:"stack",emptyLabel:"No stock exceptions match these filters."}}} getRowId={row=>String(row.id)} selectedRowId={selectedId} onRowSelect={id=>setSelectedId(id)} selectionLabel="Review" /></section>
   <aside aria-label="Selected stock exception" className="lg:sticky lg:top-[var(--space-5)]">{selected ? <RecordDetailPanel title={selected.product} subtitle={`${selected.sku} · ${selected.location}`} status={{label:replenished.includes(selected.id)?"Mock order created":selected.severity,tone:replenished.includes(selected.id)?"success":selected.severity==="Critical"?"danger":"warning"}} metadata={[{id:"cover",label:"Estimated cover",value:`${selected.daysCover} days`}]} sections={[
    {id:"stock",title:"Stock position",items:[{type:"field",id:"on-hand",label:"On hand",value:`${selected.onHand} units`},{type:"field",id:"reorder",label:"Reorder point",value:`${selected.reorderPoint} units`},{type:"field",id:"suggested",label:"Suggested replenishment",value:`${selected.suggested} units`}]},
    {id:"supplier",title:"Supplier",items:[{type:"field",id:"supplier-name",label:"Supplier",value:selected.supplier},{type:"field",id:"lead-time",label:"Lead time",value:selected.leadTime},{type:"field",id:"pack-size",label:"Order pack",value:`${selected.packSize} units`}]},
    {id:"mock",title:"Mock action",items:[{type:"note",id:"mock-note",title:replenished.includes(selected.id)?"Replenishment simulated":"Preview only",body:replenished.includes(selected.id)?`A mock replenishment for ${selected.suggested} units was created. No order was sent.`:`Try creating a replenishment for ${selected.suggested} units. This will not contact the supplier.`,tone:replenished.includes(selected.id)?"info":"warning"}]}
   ]} actions={[{id:"replenish",label:replenished.includes(selected.id)?"Mock created":`Replenish ${selected.suggested} units`,intent:"primary",disabled:replenished.includes(selected.id)}]} onAction={()=>setReplenished(c=>[...c,selected.id])} onClose={()=>setSelectedId("")} /> : <div className="rounded-[var(--radius-panel)] border border-dashed border-[var(--color-border-strong)] bg-[var(--color-bg-surface)] p-[var(--space-6)] text-[var(--color-text-secondary)]">Select a product to review stock and supplier details.</div>}</aside>
  </div>
 </div></main>;
}
